#!/usr/bin/env python3
"""Board: Work Rights on card + No Show button + clickable Outcomes tabs. Run from ~/Command-Centre."""
import base64
f="recruitment.html"
s=open(f,encoding="utf-8").read()
P=[
  ("wr_line","",""),
  ("noshow_btn","",""),
  ("fns","d2luZG93LmNvbW1pdFN0YWdlID0gZnVuY3Rpb24oaWQpewogIGNvbnN0IHNlbCA9IGRvY3VtZW50LmdldEVsZW1lbnRCeUlkKCdzdGFnZVNlbF8nK2lkKTsKICBpZiAoc2VsKSBzYXZlU3RhZ2UoaWQsIHNlbC52YWx1ZSk7Cn07",""),
  ("state","bGV0IGZTdGF0ZSA9ICJBbGwiLCBmVG93biA9ICJBbGwiOw==","bGV0IGZTdGF0ZSA9ICJBbGwiLCBmVG93biA9ICJBbGwiLCBmRHJvcCA9ICJBbGwiOw=="),
  ("outcomes","",""),
]
done=[];miss=[]
for n,ob,nb in P:
    o=base64.b64decode(ob).decode();w=base64.b64decode(nb).decode()
    if w in s: done.append(n+"(already)")
    elif o in s: s=s.replace(o,w,1);done.append(n)
    else: miss.append(n)
if miss: print("COULD NOT FIND:",miss)
else:
    open(f,"w",encoding="utf-8").write(s); print("patched OK:",done)
    print("markNoShow:",s.count("window.markNoShow"),"| Work Rights:",s.count("Work Rights:"),"| setDrop:",s.count("window.setDrop"))
